body {
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Roboto', 'Oxygen',
    'Ubuntu', 'Cantarell', 'Fira Sans', 'Droid Sans', 'Helvetica Neue',
    sans-serif;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
}

#root {
  width: 100%;
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
  padding: 20px;
}

.calculator {
  background: #1e1e1e;
  border-radius: 20px;
  box-shadow: 0 20px 60px rgba(0, 0, 0, 0.3);
  padding: 20px;
  width: 100%;
  max-width: 360px;
}

.calculator-display {
  background: #2d2d2d;
  color: #ffffff;
  font-size: 3rem;
  text-align: right;
  padding: 30px 20px;
  border-radius: 10px;
  margin-bottom: 20px;
  min-height: 100px;
  display: flex;
  align-items: center;
  justify-content: flex-end;
  word-wrap: break-word;
  word-break: break-all;
  font-weight: 300;
  letter-spacing: 1px;
}

.calculator-buttons {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 12px;
}

.btn {
  background: #3a3a3a;
  color: #ffffff;
  border: none;
  border-radius: 10px;
  font-size: 1.5rem;
  padding: 25px;
  cursor: pointer;
  transition: all 0.2s ease;
  font-weight: 500;
  outline: none;
}

.btn:hover {
  background: #4a4a4a;
  transform: scale(1.05);
}

.btn:active {
  transform: scale(0.95);
}

.btn-function {
  background: #505050;
  color: #ffffff;
}

.btn-function:hover {
  background: #606060;
}

.btn-operator {
  background: #ff9500;
  color: #ffffff;
}

.btn-operator:hover {
  background: #ffad33;
}

.btn-zero {
  grid-column: span 2;
}

@media (max-width: 400px) {
  .calculator {
    max-width: 100%;
    padding: 15px;
  }

  .calculator-display {
    font-size: 2.5rem;
    padding: 20px 15px;
    min-height: 80px;
  }

  .btn {
    font-size: 1.2rem;
    padding: 20px;
  }

  .calculator-buttons {
    gap: 8px;
  }
}

